$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$f=$mainType.GetField($name,$all);if($null-eq$f){throw "Missing field $name"};$v=$f.GetValue($window);Write-Output -NoEnumerate $v}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}
function Output([string]$port,[string]$value){$o=[Activator]::CreateInstance($outputType);$o.PortName=$port;$o.DisplayName=$port;$o.DataType='Number';$o.Value=$value;$o.Normalize(0);$o}
function ToolResult([string]$id,[string]$name,[string]$code,[string]$port,[string]$value){$r=[Activator]::CreateInstance($toolResultType);$r.ToolId=$id;$r.ToolName=$name;$r.ToolType='Measurement';$r.ResultCode=$code;$r.ElapsedMilliseconds=3.2;$r.Outputs=New-Object "System.Collections.Generic.List[$outputType]";if($port){$r.Outputs.Add((Output $port $value))};$r.Normalize(0);$r}
function Record([string]$id,[datetime]$time){$r=[Activator]::CreateInstance($recordType);$r.BatchId=$id;$r.RecipeName='S49 Recipe';$r.RecipeFingerprint=('a'*64);$r.StartedAtUtc=$time.ToUniversalTime().ToString('O');$r.CompletedAtUtc=$time.AddMinutes(1).ToUniversalTime().ToString('O');$r.Scope='All';$r.Outcome='OK';$r.AssetsEnabled=$true;$r.Items=New-Object "System.Collections.Generic.List[$itemType]";$r}
function Item([int]$sequence,[string]$name,$results){$i=[Activator]::CreateInstance($itemType);$i.Sequence=$sequence;$i.FileName=$name;$i.FilePath="D:\production\$name";$i.State='OK';$i.ResultCode='OK';$i.ToolResults=New-Object "System.Collections.Generic.List[$toolResultType]";foreach($result in $results){$i.ToolResults.Add($result)};$i}

# A: stable ToolId/Number-port trend, missing/legacy/result filters, same-name isolation, point replay and live-state isolation.
foreach($name in @('HistoricalScalarTrendExpander','HistoricalTrendToolComboBox','HistoricalTrendPortComboBox','HistoricalTrendTimeComboBox','HistoricalTrendBatchComboBox','HistoricalTrendResultComboBox','HistoricalTrendCanvas','HistoricalTrendStateText')){Assert($null-ne(Field $name)) "$name missing"}
# A correction: low-frequency commands stay behind contextual groups by default instead of filling three permanent button rows.
foreach($name in @('DeveloperMoreToggleButton','FlowMoreToggleButton','RoiToolsToggleButton','ImageMoreToggleButton')){Assert($null-ne(Field $name)) "$name missing";Assert((Field $name).IsChecked-ne$true) "$name should be collapsed by default"}
$records=Field 'batchTraceRecords';$records.Clear();$r1=Record 'S49-A' ([DateTime]::UtcNow.AddHours(-2));$i1=Item 0 'a.png' @((ToolResult 'STABLE-1' 'Diameter' 'OK' 'Value' '10'),(ToolResult 'STABLE-2' 'Diameter' 'OK' 'Value' '999'));$i2=Item 1 'b.png' @((ToolResult 'STABLE-1' 'Diameter' 'NG' 'Value' '12.5'));$r1.Items.Add($i1);$r1.Items.Add($i2)
$r2=Record 'S49-B' ([DateTime]::UtcNow.AddHours(-1));$i3=Item 0 'c.png' @((ToolResult 'STABLE-1' 'Diameter' 'ERROR' 'Value' 'bad'));$i4=Item 1 'd.png' @((ToolResult 'STABLE-1' 'Diameter' 'OK' '' ''));$legacy=Item 2 'legacy.png' @();$r2.Items.Add($i3);$r2.Items.Add($i4);$r2.Items.Add($legacy)
$store=Field 'batchTraceStore';$image=Image 160 100;$captures=New-Object "System.Collections.Generic.List[$captureType]";try{$store.SaveItemAssets($r1,$i1,$image,$image,$captures);$store.Save($r1)|Out-Null;$store.Save($r2)|Out-Null}finally{$image.Dispose()};$records.Add($r1);$records.Add($r2)
$live=Image 320 240;$mainType.GetField('currentImage',$private).SetValue($window,$live);$flowCount=(Field 'flowTools').Count;$mainType.GetMethod('RefreshHistoricalTrendOptions',$private).Invoke($window,@())|Out-Null
$tools=Field 'historicalTrendTools';Assert($tools.Count-eq2) 'Same-name different ToolId options were mixed';$selected=$tools|Where-Object ToolId -eq 'STABLE-1'|Select-Object -First 1;(Field 'HistoricalTrendToolComboBox').SelectedItem=$selected;$mainType.GetMethod('HistoricalTrendTool_Changed',$private).Invoke($window,[object[]]@($null,$null))|Out-Null
$ports=Field 'historicalTrendPorts';Assert($ports.Count-eq1-and$ports[0].PortName-eq'Value') 'Number output port discovery failed';$mainType.GetMethod('RefreshHistoricalTrend',$private).Invoke($window,@())|Out-Null;$points=Field 'historicalTrendPoints';Assert($points.Count-eq5-and($points|Where-Object HasValue).Count-eq2-and($points|Where-Object Status -eq Missing).Count-eq3) 'Trend values/missing points or legacy degradation failed';Assert((Field 'HistoricalTrendStateText').Text-match '1') 'Legacy degradation count is not visible'
(Field 'HistoricalTrendResultComboBox').SelectedValue='NG';$mainType.GetMethod('RefreshHistoricalTrend',$private).Invoke($window,@())|Out-Null;Assert((Field 'historicalTrendPoints').Count-eq1-and[double](Field 'historicalTrendPoints')[0].Value-eq12.5) 'Result filter failed';(Field 'HistoricalTrendResultComboBox').SelectedValue='All';(Field 'HistoricalTrendBatchComboBox').SelectedValue='S49-A';$mainType.GetMethod('RefreshHistoricalTrend',$private).Invoke($window,@())|Out-Null;Assert((Field 'historicalTrendPoints').Count-eq2) 'Batch filter failed';(Field 'HistoricalTrendBatchComboBox').SelectedValue='All';$mainType.GetMethod('RefreshHistoricalTrend',$private).Invoke($window,@())|Out-Null
$point=(Field 'historicalTrendPoints')|Where-Object{$_.Record.BatchId-eq'S49-A'-and$_.Item.Sequence-eq0}|Select-Object -First 1;$button=New-Object Windows.Controls.Button;$button.Tag=$point.PSObject.BaseObject;$mainType.GetMethod('HistoricalTrendPoint_Click',$private).Invoke($window,[object[]]@($button.PSObject.BaseObject,$null))|Out-Null;Assert([object]::ReferenceEquals($i1,$mainType.GetField('historicalBatchItem',$private).GetValue($window))) 'Trend point did not enter historical replay';Assert([object]::ReferenceEquals($live,$mainType.GetField('currentImage',$private).GetValue($window))-and(Field 'flowTools').Count-eq$flowCount) 'Trend replay mutated live state';Assert((Field 'HistoricalTrendToolComboBox').SelectedItem.ToolId-eq'STABLE-1' -and (Field 'HistoricalTrendBatchComboBox').SelectedValue-eq'All') 'Trend view/filter state was not retained'

# B: real circularity_xld/convexity_xld, explicit skip policy, inclusive ranges, managed lifecycle, recipe and Number/XLD downstream.
$filterKind=[Enum]::Parse($kindType,'XldCircularityConvexityFilter');$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($filterKind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($filterKind));Assert(($inputs|Where-Object PortName -eq XLD).Count-eq1-and($outputs|Where-Object PortName -eq MeanCircularity).DataType-eq'Number'-and($outputs|Where-Object PortName -eq OriginalIndices).DataType-eq'String') 'Typed circularity/convexity ports missing'
$angles=0..36|ForEach-Object{$_*[Math]::PI/18};$circleRows=[double[]]($angles|ForEach-Object{50+30*[Math]::Sin($_)});$circleColumns=[double[]]($angles|ForEach-Object{50+30*[Math]::Cos($_)});$circle=Polygon $circleRows $circleColumns;$reverse=Polygon ([double[]]([Linq.Enumerable]::Reverse($circleRows))) ([double[]]([Linq.Enumerable]::Reverse($circleColumns)));$rectangle=Polygon ([double[]]@(0,0,20,20,0)) ([double[]]@(0,40,40,0,0));$concave=Polygon ([double[]]@(0,0,20,10,20,0)) ([double[]]@(0,30,30,15,0,0));$open=Polygon ([double[]]@(0,0,20,20)) ([double[]]@(0,30,30,0));$bowtie=Polygon ([double[]]@(0,20,0,20,0)) ([double[]]@(0,20,20,0,0));$degenerate=Polygon ([double[]]@(0,0,0,0)) ([double[]]@(0,5,10,0));$input=Concat @($circle,$reverse,$rectangle,$concave,$open,$bowtie,$degenerate);foreach($x in @($circle,$reverse,$rectangle,$concave,$open,$bowtie,$degenerate)){$x.Dispose()}
$filter=Tool XldCircularityConvexityFilter 'S49 Circularity Convexity';$run=$mainType.GetMethod('RunXldCircularityConvexityFilterTool',$private);function RunFilter($x){try{$run.Invoke($window,[object[]]@($filter,$x.PSObject.BaseObject))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
try{$filter.Parameters.XldCircularityMinimum=0;$filter.Parameters.XldCircularityMaximum=1;$filter.Parameters.XldConvexityMinimum=0;$filter.Parameters.XldConvexityMaximum=1;$filter.Parameters.XldCircularityConvexityClosureTolerance=0;$result=RunFilter $input;Assert($result.ResultCode-eq'OK'-and[int](Out $filter ContourCount)-eq4-and(Out $filter OriginalIndices)-eq'[1,2,3,4]') 'All valid contours/stable indices failed';Assert([int](Out $filter InputOpenCount)-eq1-and[int](Out $filter SelfIntersectingCount)-eq1-and[int](Out $filter DegenerateCount)-eq1) 'Open/self-intersecting/degenerate skip counters failed';Assert([Math]::Abs([double](Out $filter MeanCircularity)-[double](Out $filter MeanCircularity))-lt1e-12-and[double](Out $filter MaxConvexity)-le1) 'Finite statistics failed';$old=Out $filter XLD;$filter.Parameters.XldCircularityMinimum=.9;RunFilter $input|Out-Null;Assert((Out $filter OriginalIndices)-eq'[1,2]'-and$old.IsDisposed) 'Circle selection/reversal or old snapshot release failed';$filter.Parameters.XldCircularityMinimum=0;$filter.Parameters.XldConvexityMinimum=.99;RunFilter $input|Out-Null;Assert((Out $filter OriginalIndices)-match '^\[1,2,3\]$') 'Convexity selection failed';[HalconDotNet.HTuple]$count=$null;[HalconDotNet.HOperatorSet]::CountObj($input,[ref]$count);Assert($count.I-eq7) 'Upstream ownership changed'}finally{$input.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$filter.Parameters.XldConvexityMinimum=0;$emptyResult=RunFilter $empty;Assert($emptyResult.ResultCode-eq'NG'-and[int](Out $filter ContourCount)-eq0) 'Empty input semantics failed'}finally{$empty.Dispose()}
$existingFlow=Field 'flowTools';$existingFlow.Add($filter)
$filter.Parameters.XldCircularityMinimum=1;$filter.Parameters.XldCircularityMaximum=.9;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Invalid circularity range accepted';$filter.Parameters.XldCircularityMinimum=0;$filter.Parameters.XldCircularityMaximum=1;$filter.Parameters.XldConvexityMinimum=-.1;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Invalid convexity range accepted';$filter.Parameters.XldConvexityMinimum=0;$filter.Parameters.XldCircularityConvexityClosureTolerance=-1;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Invalid closure tolerance accepted'
$flow=Field 'flowTools';$producer=Tool XldPointClosureFilter 'Geometry Source';$chain=Tool XldCircularityConvexityFilter 'Geometry Shape Filter';$judge=Tool NumericJudge 'Geometry Count Judge';$chain.Parameters.XldCircularityMinimum=0;$chain.Parameters.XldCircularityMaximum=1;$chain.Parameters.XldConvexityMinimum=0;$chain.Parameters.XldConvexityMaximum=1;$chain.Parameters.XldCircularityConvexityClosureTolerance=0;$chain.SetInputBinding('XLD',$producer.ToolId,'XLD');$judge.SetInputBinding('Value',$chain.ToolId,'ContourCount');$judge.InputToolId=$chain.ToolId;$judge.InputPortName='ContourCount';$judge.NumericLowerLimit=1;$judge.NumericUpperLimit=1;$flow.Add($producer);$flow.Add($chain);$flow.Add($judge);$source=Polygon $circleRows $circleColumns;try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($source.PSObject.BaseObject,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$source.Dispose()};$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$execute.Invoke($window,[object[]]@($chain,'S49 chain'))|Out-Null;$execute.Invoke($window,[object[]]@($judge,'S49 chain'))|Out-Null;Assert($chain.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Real XLD/Number downstream chain failed'
(Field 'FlowToolList').SelectedItem=$filter;$filter.Parameters.XldCircularityMinimum=.25;$filter.Parameters.XldCircularityMaximum=.95;$filter.Parameters.XldConvexityMinimum=.5;$filter.Parameters.XldConvexityMaximum=1;$filter.Parameters.XldCircularityConvexityClosureTolerance=2;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($filter))|Out-Null;Assert((Field 'DockXldCircularityConvexityFilterPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldCircularityMinimumTextBox').Text-eq'0.25') 'Dock configuration synchronization failed';$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object{$_.ToolId-eq$filter.ToolId}|Select-Object -First 1;Assert($saved.Parameters.XldCircularityMinimum-eq.25-and$saved.Parameters.XldConvexityMinimum-eq.5-and$saved.Parameters.XldCircularityConvexityClosureTolerance-eq2) 'Recipe persistence failed';$released=Out $producer XLD;$released.Dispose();$failed=$false;try{$execute.Invoke($window,[object[]]@($chain,'released upstream'))|Out-Null}catch{$failed=$true};Assert $failed 'Released upstream XLD was accepted'
$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S49 historical scalar trend and HALCON XLD circularity/convexity filter smoke tests passed.'
